const now = new Date();
const batchId = (typeof crypto !== 'undefined' && crypto.randomUUID)
  ? crypto.randomUUID()
  : `${now.toISOString().replace(/[:.]/g, '-')}-${Math.random().toString(36).slice(2, 10)}`;
return [{
  json: {
    batch_id: batchId,
    started_at: now.toISOString(),
    embedding_model: $env.RAG_EVAL_EMBEDDING_MODEL || 'text-embedding-3-small',
    llm_model: $env.RAG_EVAL_LLM_MODEL || 'gpt-4o-mini',
    judge_model: $env.RAG_JUDGE_MODEL || $env.RAG_EVAL_LLM_MODEL || 'gpt-4o-mini'
  }
}];

const result = $('Run Eval Batch').first()?.json ?? {};
const prep = $('Prepare Batch ID').first()?.json ?? {};
const now = new Date().toISOString();

const summary = {
  timestamp: now,
  workflow: 'WF_RAG_EVAL_NIGHTLY',
  batch_id: result.batch_id || prep.batch_id,
  ok: result.ok === true,
  embedding_model: result.embedding_model,
  llm_model: result.llm_model,
  judge_model: result.judge_model,
  golden_total: result.golden_total ?? 0,
  scored: result.scored ?? 0,
  failed: result.failed ?? 0,
  baseline_rows_upserted: result.baseline_rows_upserted ?? 0,
  duration_ms: result.duration_ms ?? 0,
  failures_sample: (result.failures || []).slice(0, 5)
};

if (!summary.ok || summary.failed > summary.scored * 0.2) {
  summary.severity = 'warn';
  summary.message = `RAG eval batch had ${summary.failed} failures out of ${summary.golden_total}`;
} else {
  summary.severity = 'info';
  summary.message = `RAG eval batch ok: ${summary.scored}/${summary.golden_total} scored, ${summary.baseline_rows_upserted} baseline rows`;
}

return [{ json: summary }];

// Classify regression results — derive top-line severity for the batch.
// Input: array of regression rows (one per (profile, embedding, llm) group)
// from fn_detect_rag_baseline_regression. Output: single summary row used by
// both the audit log and the Matrix alert.
const summary = $('Log Results').first()?.json ?? {};
const regressionRaw = $('Detect Regressions').first()?.json ?? [];
const regressions = Array.isArray(regressionRaw) ? regressionRaw : [];

const critical = regressions.filter((r) => r.severity === 'critical');
const warning = regressions.filter((r) => r.severity === 'warning');

let topSeverity = summary.severity || 'info';
if (critical.length > 0) topSeverity = 'critical';
else if (warning.length > 0 && topSeverity !== 'critical') topSeverity = 'warn';

const formatRow = (r) =>
  `  - ${r.context_profile_slug || '(default)'} / ${r.embedding_model} / ${r.llm_model}: ` +
  `${r.latest_composite ?? 'n/a'} vs ${r.lookback_avg_composite ?? 'n/a'} ` +
  `(drop ${r.drop_absolute ?? 0}, ${(((r.drop_pct ?? 0) * 100).toFixed(2))}%) [${r.severity}: ${r.reason}]`;

let alertText = '';
if (critical.length > 0) {
  alertText += `*RAG eval — CRITICAL regression on ${critical.length} group(s)*\n`;
  alertText += critical.map(formatRow).join('\n') + '\n';
}
if (warning.length > 0) {
  alertText += `*RAG eval — warning regression on ${warning.length} group(s)*\n`;
  alertText += warning.map(formatRow).join('\n') + '\n';
}
if (critical.length === 0 && warning.length === 0) {
  alertText = `RAG eval — all groups within tolerance (${regressions.length} compared)`;
}

return [{
  json: {
    ...summary,
    regression_top_severity: topSeverity,
    regression_critical_count: critical.length,
    regression_warning_count: warning.length,
    regression_total_groups: regressions.length,
    regression_alert_text: alertText.trim(),
    regression_groups: regressions
  }
}];
